mapper.select:
SELECT ai.id, ai.name, ai.introduction, ai.district_id, ai.district_name, ai.city_id, ai.city_name, ai.province_id, ai.province_name, ai.address_detail, ai.latitude, ai.longitude, ai.phone, ai.is_release, IFNULL(tc.cnt, 0) AS total_room_count, IFNULL(tc.cnt, 0) - IFNULL(lc.cnt, 0) AS free_room_count FROM apartment_info ai LEFT JOIN (SELECT apartment_id, count(*) AS cnt FROM room_info WHERE is_deleted = 0 AND is_release = 1 GROUP BY apartment_id) tc ON ai.id = tc.apartment_id LEFT JOIN (SELECT apartment_id, COUNT(*) AS cnt FROM lease_agreement WHERE is_deleted = 0 AND status in (2, 5) GROUP BY apartment_id) lc ON ai.id = lc.apartment_id WHERE ai.is_deleted = 0
AND province_id=#{queryVo.provinceId}
AND city_id=#{queryVo.cityId}
AND district_id=#{queryVo.districtId}
